function prepareHistoricalQuery({ customerId, managerId, keywords }) {
  const isId = (value) => typeof value === "string" && /^\d{10}$/.test(value);
  if (!isId(customerId) || !(managerId === "" || isId(managerId)))
    throw Error("Use 10-digit Google Ads account IDs without dashes.");
  if (
    !Array.isArray(keywords) ||
    !keywords.length ||
    keywords.length > 20 ||
    keywords.some((value) => typeof value !== "string" || !value.trim())
  ) {
    throw Error("Enter an array of 1 to 20 nonempty keywords.");
  }
  return {
    endpoint: "/customers/" + customerId + ":generateKeywordHistoricalMetrics",
    headers: managerId ? { "login-customer-id": managerId } : {},
    body: { keywords: keywords.map((word) => word.trim()), keywordPlanNetwork: "GOOGLE_SEARCH" },
  };
}
const settings = {
  customerId: "YOUR_ADS_CUSTOMER_ID",
  managerId: "",
  keywords: ["desk lamp", "desk lamps", "task lighting"],
};
return [{ json: prepareHistoricalQuery(settings), pairedItem: { item: 0 } }];

function returnedKeywordGroups({ statusCode, body }) {
  if (
    statusCode !== 200 ||
    !body ||
    typeof body !== "object" ||
    Array.isArray(body) ||
    body.error
  ) {
    throw Error("Google Ads did not return historical keyword metrics (HTTP " + statusCode + ").");
  }
  const rows = body.results ?? [];
  if (
    !Array.isArray(rows) ||
    rows.some(
      (row) =>
        typeof row?.text !== "string" ||
        !row.text ||
        (row.closeVariants !== undefined &&
          (!Array.isArray(row.closeVariants) ||
            row.closeVariants.some((word) => typeof word !== "string"))) ||
        (row.keywordMetrics !== undefined &&
          (!row.keywordMetrics ||
            typeof row.keywordMetrics !== "object" ||
            Array.isArray(row.keywordMetrics))),
    )
  ) {
    throw Error("Google Ads returned an unexpected keyword metrics response.");
  }
  return rows;
}
return returnedKeywordGroups($input.first().json).map((json) => ({
  json,
  pairedItem: { item: 0 },
}));
